script:
(function () {
  'use strict';
  // Tax-sheltered annuity (403(b)): the same contributions invested two ways - an insurance annuity contract
  // (403(b)(1)) and a mutual fund custodial account (403(b)(7)). Each year you defer contrib% of pay and the
  // employer may match match% of it up to matchCap% of pay. Deposits go in monthly. Each account grows at the
  // monthly equivalent of (gross return - its yearly % costs), the net-of-fee convention used by
  // 403b-savings-calculator; the % cost charged each month is the gap to the gross monthly growth, and a flat
  // yearly fee comes out in 12 equal parts. Annuity surrender charge: starts at surr% in contract year 1 and
  // falls by surr / period each contract year to 0 after the surrender period; it applies to the contract
  // value if cashed out or moved at that year end (contract year = years already open + projection year).
  // Limits (when applied): 402(g) deferral + age catch-up; 415(c) caps deferrals (excl. catch-up) + employer.
  // Checked in Node (scratchpad solo401k/tests/ta.test.js): $500/month, 0 costs, 30 years at 7% = $584,726
  // in both accounts; costs of 2% at 7% equal the 5% no-cost value ($407,688); 7% over 7 years -> 7, 6, ..., 1,
  // then 0%; 3 years already open -> 4% in the first projection year; caps $24,500 (age 40), $32,500 (55),
  // $35,750 (61); a $30 contract fee on a 0% return removes exactly $30 a year.
  // ---- 2026 IRS limits (IRS Notice 2025-67, tax year 2026) ---------------------------------------------
  var LIMITS = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit (pre-tax + Roth 403(b))
    catchUp50: 8000,        // 414(v) catch-up, age 50 or older by year-end
    catchUp60to63: 11250,   // SECURE 2.0 higher catch-up, ages 60-63 (instead of the age-50 amount)
    annualAdditions: 72000, // 415(c) limit on deferrals + employer contributions (age catch-up excluded)
    compensation: 360000    // 401(a)(17) pay limit for employer contributions
  };
  // ------------------------------------------------------------------------------------------------------

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }
  // Surrender charge rate in contract year n (1-based).
  function surrenderRate(first, period, n) {
    if (period <= 0 || n > period) return 0;
    return Math.max(0, first * (period - n + 1) / period);
  }

  // One account: grows a balance with deposits[] (yearly totals) at rate less pctCost, minus flat fee.
  function grow(balance, deposits, rate, pctCost, flat) {
    var mGross = Math.pow(1 + rate, 1 / 12) - 1, mNet = Math.pow(Math.max(0, 1 + rate - pctCost), 1 / 12) - 1;
    var bal = balance, costs = 0, ends = [];
    deposits.forEach(function (d) {
      for (var m = 0; m < 12; m++) {
        var pct = bal * (mGross - mNet), fee = Math.min(flat / 12, bal * (1 + mNet));
        bal = bal * (1 + mNet) - fee + d / 12;
        costs += pct + fee;
      }
      ends.push(bal);
    });
    return { balance: bal, costs: costs, ends: ends };
  }

  // p: age, retireAge, salary, raise, balance, contrib, match, matchCap, rate, inflation (decimals), applyLimits,
  //    ann: { fund, me, surr, period, fee, open }, cus: { fund, fee } (rates as decimals).
  function project(p) {
    var years = p.retireAge - p.age, salary = p.salary, deps = [], rows = [], capped = false, totYou = 0, totEr = 0;
    var first = null;
    for (var y = 0; y < years; y++) {
      var a = p.age + y, pay = p.applyLimits ? Math.min(salary, LIMITS.compensation) : salary;
      var you = salary * p.contrib, limit = Infinity;
      if (p.applyLimits) {
        limit = LIMITS.deferral + catchUpFor(a);
        if (you > limit) { you = limit; capped = true; }
      }
      var effPct = salary > 0 ? Math.min(you / salary, p.contrib) : 0;
      var er = pay * p.match * Math.min(effPct, p.matchCap);
      if (p.applyLimits) {
        var regular = Math.min(you, LIMITS.deferral);
        if (regular + er > LIMITS.annualAdditions) { er = Math.max(0, LIMITS.annualAdditions - regular); capped = true; }
      }
      if (y === 0) first = { you: you, er: er, limit: limit };
      deps.push(you + er); totYou += you; totEr += er;
      rows.push({ age: a, dep: you + er });
      salary = salary * (1 + p.raise);
    }
    var ann = grow(p.balance, deps, p.rate, p.ann.fund + p.ann.me, p.ann.fee);
    var cus = grow(p.balance, deps, p.rate, p.cus.fund, p.cus.fee);
    rows.forEach(function (row, i) {
      var sr = surrenderRate(p.ann.surr, p.ann.period, p.ann.open + i + 1);
      row.ann = ann.ends[i]; row.surr = ann.ends[i] * sr; row.cash = ann.ends[i] - row.surr; row.cus = cus.ends[i];
    });
    return { ann: ann, cus: cus, rows: rows, you: totYou, er: totEr, capped: capped, first: first,
             real: cus.balance / Math.pow(1 + p.inflation, years) };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }
  function pctText(x) { return (Math.round(x * 10000) / 100) + '%'; }

  function update() {
    var v = {};
    ['Age', 'RetireAge', 'Salary', 'Raise', 'Balance', 'Contrib', 'Match', 'MatchCap', 'Rate', 'Inflation', 'AnnFund', 'AnnMe',
     'AnnSurr', 'AnnSurrYears', 'AnnFee', 'AnnOpen', 'CusFund', 'CusFee'].forEach(function (k) { v[k] = num('ta' + k); });
    var applyLimits = document.getElementById('taLimits').checked;
    var error = document.getElementById('taError');
    var bad = Object.keys(v).some(function (k) { return isNaN(v[k]); }) ||
              v.Age !== Math.round(v.Age) || v.RetireAge !== Math.round(v.RetireAge) || v.Age < 16 || v.Age > 99 ||
              v.RetireAge <= v.Age || v.RetireAge > 100 || v.Salary < 0 || v.Balance < 0 || v.Raise < 0 || v.Raise > 20 ||
              v.Contrib < 0 || v.Contrib > 100 || v.Match < 0 || v.Match > 200 || v.MatchCap < 0 || v.MatchCap > 100 ||
              v.Rate < 0 || v.Rate > 30 || v.Inflation < 0 || v.Inflation > 20 ||
              [v.AnnFund, v.AnnMe, v.CusFund].some(function (x) { return x < 0 || x > 5; }) ||
              v.AnnSurr < 0 || v.AnnSurr > 20 || v.AnnSurrYears < 0 || v.AnnSurrYears > 20 ||
              v.AnnSurrYears !== Math.round(v.AnnSurrYears) || v.AnnOpen < 0 || v.AnnOpen > 60 || v.AnnOpen !== Math.round(v.AnnOpen) ||
              v.AnnFee < 0 || v.AnnFee > 1000 || v.CusFee < 0 || v.CusFee > 1000;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter whole-number ages from 16 to 99 with retirement above your age (up to 100), non-negative amounts, ' +
                          'percentages from 0 to 100 (match up to 200%), a return up to 30%, yearly costs up to 5%, a surrender ' +
                          'charge up to 20% over up to 20 whole years, and flat fees up to $1,000.';
      return;
    }
    var p = { age: v.Age, retireAge: v.RetireAge, salary: v.Salary, raise: v.Raise / 100, balance: v.Balance,
              contrib: v.Contrib / 100, match: v.Match / 100, matchCap: v.MatchCap / 100, rate: v.Rate / 100,
              inflation: v.Inflation / 100, applyLimits: applyLimits,
              ann: { fund: v.AnnFund / 100, me: v.AnnMe / 100, surr: v.AnnSurr / 100, period: v.AnnSurrYears, fee: v.AnnFee, open: v.AnnOpen },
              cus: { fund: v.CusFund / 100, fee: v.CusFee } };
    var r = project(p);
    set('taCusBal', fmt(r.cus.balance)); set('taAnnBal', fmt(r.ann.balance));
    var diff = r.cus.balance - r.ann.balance;
    set('taDiff', (diff < -0.5 ? '−' : '') + fmt(Math.abs(diff)));
    set('taContribTotal', fmt(r.you + r.er)); set('taAnnCost', fmt(r.ann.costs)); set('taCusCost', fmt(r.cus.costs));
    var base = Math.max(r.cus.balance, r.ann.balance);
    set('taVerdict', Math.abs(diff) < 0.5 ? 'Both options end up with the same balance at ' + p.retireAge + '.'
      : (diff > 0 ? 'The custodial account' : 'The annuity contract') + ' ends up ' + fmt(Math.abs(diff)) + ' ahead at age ' +
        p.retireAge + ', ' + Math.round(Math.abs(diff) / base * 100) + '% of the larger balance, from the same contributions and investments.');
    var f = r.first;
    set('taYrYou', fmt(f.you)); set('taYrEr', fmt(f.er));
    set('taYrLimit', applyLimits ? fmt(f.limit) : 'Limits not applied');
    set('taYrCost', pctText(p.ann.fund + p.ann.me) + ' vs ' + pctText(p.cus.fund));
    set('taReal', fmt(r.real));
    var capEl = document.getElementById('taCapped');
    capEl.hidden = !r.capped;
    if (r.capped) set('taCapped', 'In some years your contribution or your employer\'s is reduced to stay within the ' + LIMITS.year + ' IRS limits.');
    var body = document.getElementById('taSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, fmt(row.dep), fmt(row.ann), fmt(row.surr), fmt(row.cash), fmt(row.cus)].forEach(function (x) {
        var td = document.createElement('td'); td.textContent = x; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('taForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
